function collectionProducts(key, query){
  let list=products.slice();
  if(key==='best-sellers')list=list.filter(p=>p.bestSeller&&String(p.img).startsWith('assets/')).sort((a,b)=>b.popularity-a.popularity);
  else if(key==='men-best-sellers')list=list.filter(p=>p.bestSeller&&p.gender==='Men'&&String(p.img).startsWith('assets/')).sort((a,b)=>b.popularity-a.popularity);
  else if(key==='women-best-sellers')list=list.filter(p=>p.bestSeller&&p.gender==='Women'&&p.category==='Jeans'&&String(p.img).startsWith('assets/')).sort((a,b)=>b.popularity-a.popularity);
  else if(key==='women-clearance')list=list.filter(p=>p.gender==='Women'&&p.clearance===true&&String(p.img).startsWith('assets/'));
  else if(key==='men-trousers')list=list.filter(p=>p.gender==='Men'&&p.category==='Trousers'&&String(p.img).startsWith('assets/'));
  else if(key==='men-shirts')list=list.filter(p=>p.gender==='Men'&&p.category==='Shirts'&&String(p.img).startsWith('assets/'));
  else if(key==='men-t-shirts')list=list.filter(p=>p.gender==='Men'&&p.category==='T-shirts'&&String(p.img).startsWith('assets/'));
  else if(key==='men')list=list.filter(p=>(p.gender==='Men'||p.gender==='Unisex')&&String(p.img).startsWith('assets/'));
  else if(key==='women')list=list.filter(p=>p.gender==='Women'&&String(p.img).startsWith('assets/'));
  else if(key==='women-trousers')list=list.filter(p=>p.gender==='Women'&&p.category==='Trousers'&&String(p.img).startsWith('assets/'));
  else if(key==='women-tops')list=list.filter(p=>p.gender==='Women'&&p.category==='Tops'&&String(p.img).startsWith('assets/'));
  else if(key==='new-arrivals')list=list.filter(p=>(p.gender==='Men'||p.gender==='Women')&&String(p.img).startsWith('assets/'));
  else if(key==='jeans')list=list.filter(p=>p.category==='Jeans');
  else if(key==='t-shirts')list=list.filter(p=>p.category==='T-shirts'&&String(p.img).startsWith('assets/'));
  else if(key==='shirts')list=list.filter(p=>p.category==='Shirts'&&String(p.img).startsWith('assets/'));
  else if(key==='trousers')list=list.filter(p=>p.category==='Trousers'&&String(p.img).startsWith('assets/')).sort((a,b)=>b.popularity-a.popularity);
  else if(key==='casual-wear')list=list.filter(p=>p.category==='Casual Wear');
  else if(key==='wishlist')list=list.filter(p=>wishlist.includes(p.id));
  else if(key==='search'){const q=(query||'').toLowerCase().trim();list=list.filter(p=>(p.name+' '+p.category+' '+p.color+' '+p.fit).toLowerCase().includes(q))}
  return list;
}
