function renderNotFound(){main.innerHTML='<section class="collection-content"><div class="empty-state"><h2>That page wandered off.</h2><p>Explore the latest pieces and find your way back.</p><a href="index.html" data-home class="button button-dark">Back to OFF DUTY</a></div></section>'}
function renderRoute(){
  const params=currentParams();
  const product=params.get('product');
  const key=params.get('collection');
  if(product)renderProduct(product);else if(key)renderCollection(key,params.get('q')||'');else renderHome();
  updateCounts();
}
function updateCounts(){
  const count=totalItems();
  document.querySelectorAll('.cart-count').forEach(el=>el.textContent=count);
  document.querySelectorAll('.wishlist-count').forEach(el=>{el.textContent=wishlist.length;el.hidden=!wishlist.length});
  document.querySelector('.drawer-count').textContent='('+count+')';
}
function saveCart(){storage.set('od-cart',cart);updateCounts();renderCart()}
function saveWishlist(){storage.set('od-wishlist',wishlist);updateCounts()}
function addToCart(id,size,qty){
  const p=byId(id);if(!p)return;
  const key=id+'|'+size;const existing=cart.find(i=>i.key===key);
  if(existing)existing.qty+=qty;else cart.push({key,id,size,qty});
  saveCart();showToast(p.name+' added to your bag');openCart();
}
function renderCart(){
  const lines=document.getElementById('cart-lines'), footer=document.getElementById('cart-footer');
  if(!cart.length){lines.innerHTML='<div class="cart-empty"><span class="eyebrow">A LITTLE ROOM FOR SOMETHING GOOD</span><h3>Your bag is taking a breather.</h3><p>Your saved pieces will be here when you are ready.</p><button class="button button-dark" type="button" data-close-cart>Continue shopping</button></div>';footer.innerHTML='';return}
  lines.innerHTML=cart.map(item=>{const p=byId(item.id);if(!p)return '';return '<div class="cart-line"><a href="?product='+p.id+'" data-product="'+p.id+'"><img src="'+imgUrl(p.img,300)+'" alt="'+esc(p.alt)+'"></a><div class="cart-line-info"><a class="cart-line-title" href="?product='+p.id+'" data-product="'+p.id+'">'+esc(p.name)+'</a><span class="cart-line-size">Size: '+esc(item.size)+' &nbsp;·&nbsp; '+esc(p.color)+'</span><span class="cart-line-price">'+money(p.price)+'</span><div class="cart-line-controls"><div class="cart-quantity"><button type="button" data-cart-action="minus" data-key="'+esc(item.key)+'" aria-label="Decrease quantity">−</button><span>'+item.qty+'</span><button type="button" data-cart-action="plus" data-key="'+esc(item.key)+'" aria-label="Increase quantity">+</button></div><button type="button" class="remove-item" data-cart-action="remove" data-key="'+esc(item.key)+'">Remove</button></div></div></div>'}).join('');
  const subtotal=cart.reduce((sum,item)=>sum+(byId(item.id)?.price||0)*item.qty,0);
  footer.innerHTML='<div class="subtotal-row"><span>Subtotal</span><span>'+money(subtotal)+'</span></div><p class="demo-note">Sample prices shown for this university demonstration. No purchase or payment will be taken.</p><button type="button" class="button button-primary" data-info="checkout">Continue to demo checkout &nbsp; ↗</button>';
}
function openCart(){renderCart();cartDrawer.hidden=false;drawerBackdrop.hidden=false;document.body.classList.add('no-scroll');document.querySelector('.close-drawer').focus()}
function closeCart(){cartDrawer.hidden=true;drawerBackdrop.hidden=true;document.body.classList.remove('no-scroll')}
function closeMobile(){mobileNav.hidden=true;document.getElementById('menu-toggle').setAttribute('aria-expanded','false');document.getElementById('menu-toggle').setAttribute('aria-label','Open navigation')}
function showToast(message){toast.textContent=message;toast.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('is-visible'),2200)}
const infoCopy={
 account:['Your OFF DUTY','This is a storefront demonstration. Account sign-in is not connected, and no personal details are collected.'],
 about:['Off the clock. All your own.','OFF DUTY is a university storefront concept for considered everyday style. We believe the best wardrobe makes room for your own point of view.'],
 contact:['Say hello','This demo has no live customer-service inbox. For an assignment walkthrough, use the contact details provided by your course.'],
 faq:['Frequently asked','This is a frontend-only demonstration. Browse collections, save favourites and try the sample shopping bag. No real accounts, orders or payments are created.'],
 shipping:['Shipping information','Shipping details are shown as sample content for the assignment. This storefront does not fulfil or ship products.'],
 returns:['Returns information','Returns information is included for demonstration only. No real order or return request can be placed.'],
 privacy:['Privacy','This demo stores your cart and wishlist in this browser’s local storage. Newsletter entries are checked in the browser and are not sent to a server.'],
 social:['Follow along','OFF DUTY is a fictional university project brand. Social links are not connected to live brand accounts.'],
 size:['A note on sizing','Choose the size you usually wear for a relaxed, everyday fit. This guide is sample content; use the product fit description as a visual reference.'],
 checkout:['Demo checkout','You are at the end of the sample shopping flow. This is a frontend demonstration only: no payment, order or personal information is collected.']
};
function openInfo(key){
  if(key==='quick-size'){return}
  const item=infoCopy[key]||infoCopy.about;
  infoContent.innerHTML='<span class="demo-label">Frontend demonstration</span><h2 id="info-title">'+esc(item[0])+'</h2><p>'+esc(item[1])+'</p>'+(key==='checkout'?'<button class="button button-dark" data-close-info type="button">Keep exploring</button>':'');
  if(!infoDialog.open)infoDialog.showModal();
}
function openQuickAdd(id){
  const p=byId(id);if(!p)return;
  activeProduct=p;selectedProductSize='';
  infoContent.innerHTML='<span class="demo-label">Quick add</span><h2 id="info-title">'+esc(p.name)+'</h2><p>'+money(p.price)+' &nbsp;·&nbsp; '+esc(p.color)+'</p><div class="option-label"><span>Choose a size</span></div><div class="size-options quick-sizes">'+p.sizes.map(s=>'<button type="button" class="size-option" data-quick-size="'+esc(s)+'" aria-pressed="false">'+esc(s)+'</button>').join('')+'</div><div class="size-error" id="quick-size-error" aria-live="polite"></div><button type="button" class="button button-primary" style="width:100%;margin-top:15px" data-quick-confirm="'+esc(id)+'">Add to bag &nbsp; +</button>';
  infoDialog.showModal();
}
function setWishlist(id){
  if(wishlist.includes(id)){wishlist=wishlist.filter(x=>x!==id);showToast('Removed from your wishlist')}
  else{wishlist.push(id);showToast('Saved to your wishlist')}
  saveWishlist();
  const p=byId(id);
  if(p&&currentParams().get('product')===id)renderProduct(id);
  else if(currentParams().get('collection'))updateCollectionGrid(currentParams().get('collection'),currentParams().get('q')||'');
}
function openSearch(){searchDialog.showModal();setTimeout(()=>document.getElementById('search-input').focus(),50);renderSuggestions('')}
function renderSuggestions(query){
  const box=document.getElementById('search-suggestions');
  if(query.trim().length<2){box.innerHTML='<h3>Start somewhere</h3><div class="suggestion-list">'+['Denim','Everyday tees','New arrivals','Relaxed fit'].map((x,i)=>'<button type="button" data-search-term="'+esc(['jeans','tee','new','relaxed'][i])+'">'+esc(x)+'</button>').join('')+'</div>';return}
  const results=products.filter(p=>String(p.img).startsWith('assets/')&&(p.name+' '+p.category+' '+p.color+' '+p.fit).toLowerCase().includes(query.toLowerCase())).slice(0,5);
  box.innerHTML=results.length?'<h3>Pieces for your search</h3>'+results.map(p=>'<a class="suggestion-result" href="?product='+p.id+'" data-product="'+p.id+'">'+esc(p.name)+' <span>'+money(p.price)+'</span></a>').join(''):'<p class="search-empty">No matches yet. Try denim, tee or shirt.</p>';
}
function updateQuantity(delta){
  selectedQuantity=Math.max(1,Math.min(10,selectedQuantity+delta));
  const el=document.getElementById('detail-quantity');if(el)el.textContent=selectedQuantity;
}
function searchSubmit(query){navigate('collection=search&q='+encodeURIComponent(query))}
document.addEventListener('click',event=>{
  const womenCategory=event.target.closest('[data-women-category]');
  if(womenCategory){event.preventDefault();if(['women-trousers','women-tops','women-best-sellers','women-clearance'].includes(womenCategory.dataset.womenCategory)){navigate('collection='+womenCategory.dataset.womenCategory);return}const select=document.getElementById('filter-category');if(select){select.value=womenCategory.dataset.womenCategory;updateCollectionGrid('women','')}document.getElementById('collection-grid')?.scrollIntoView({behavior:'smooth',block:'start'});return}
  const route=event.target.closest('[data-collection]');
  if(route){event.preventDefault();navigate('collection='+encodeURIComponent(route.dataset.collection));return}
  const home=event.target.closest('[data-home]');
  if(home){event.preventDefault();navigate('');return}
  const productLink=event.target.closest('[data-product]');
  if(productLink){event.preventDefault();closeCart();if(infoDialog.open)infoDialog.close();if(searchDialog.open)searchDialog.close();navigate('product='+encodeURIComponent(productLink.dataset.product));return}
  const scroll=event.target.closest('[data-scroll]');
  if(scroll){event.preventDefault();if(currentParams().has('collection')||currentParams().has('product')){history.pushState({},'','index.html');renderHome()}closeMobile();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}
  const top=event.target.closest('[data-top]');if(top){event.preventDefault();window.scrollTo({top:0,behavior:'smooth'});return}
  const favorite=event.target.closest('[data-wishlist]');if(favorite){event.preventDefault();setWishlist(favorite.dataset.wishlist);return}
  const quick=event.target.closest('[data-quick-add]');if(quick){openQuickAdd(quick.dataset.quickAdd);return}
  const quickSize=event.target.closest('[data-quick-size]');if(quickSize){document.querySelectorAll('[data-quick-size]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});quickSize.classList.add('selected');quickSize.setAttribute('aria-pressed','true');selectedProductSize=quickSize.dataset.quickSize;document.getElementById('quick-size-error').textContent='';return}
  const quickConfirm=event.target.closest('[data-quick-confirm]');if(quickConfirm){if(!selectedProductSize){document.getElementById('quick-size-error').textContent='Please choose a size to continue.';return}const id=quickConfirm.dataset.quickConfirm;const size=selectedProductSize;infoDialog.close();addToCart(id,size,1);return}
  const size=event.target.closest('[data-size]');if(size){document.querySelectorAll('[data-size]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});size.classList.add('selected');size.setAttribute('aria-pressed','true');selectedProductSize=size.dataset.size;document.getElementById('size-error').textContent='';return}
  const color=event.target.closest('[data-color]');if(color){document.querySelectorAll('[data-color]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});color.classList.add('selected');color.setAttribute('aria-pressed','true');document.getElementById('selected-color').textContent=color.dataset.color;return}
  const qty=event.target.closest('[data-qty]');if(qty){updateQuantity(Number(qty.dataset.qty));return}
  const addDetail=event.target.closest('[data-add-detail]');if(addDetail){if(!selectedProductSize){document.getElementById('size-error').textContent='Select a size to add this piece to your bag.';return}addToCart(addDetail.dataset.addDetail,selectedProductSize,selectedQuantity);return}
  const cartAction=event.target.closest('[data-cart-action]');if(cartAction){const item=cart.find(i=>i.key===cartAction.dataset.key);if(!item)return;if(cartAction.dataset.cartAction==='remove')cart=cart.filter(i=>i.key!==item.key);else if(cartAction.dataset.cartAction==='plus')item.qty++;else item.qty=Math.max(1,item.qty-1);saveCart();return}
  if(event.target.closest('[data-close-cart]')){closeCart();return}
  if(event.target.closest('[data-close-info]')){infoDialog.close();return}
  const info=event.target.closest('[data-info]');if(info){openInfo(info.dataset.info);return}
  const term=event.target.closest('[data-search-term]');if(term){document.getElementById('search-input').value=term.dataset.searchTerm;searchSubmit(term.dataset.searchTerm);searchDialog.close();return}
});
document.getElementById('menu-toggle').addEventListener('click',()=>{const open=mobileNav.hidden;mobileNav.hidden=!open;document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));document.getElementById('menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation')});
document.getElementById('search-open').addEventListener('click',openSearch);
document.getElementById('cart-open').addEventListener('click',openCart);
document.querySelector('.close-drawer').addEventListener('click',closeCart);
drawerBackdrop.addEventListener('click',closeCart);
document.querySelectorAll('.dialog-close').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.getElementById('search-input').addEventListener('input',event=>renderSuggestions(event.target.value));
document.getElementById('search-form').addEventListener('submit',event=>{event.preventDefault();const q=document.getElementById('search-input').value.trim();if(q){searchDialog.close();searchSubmit(q)}});
main.addEventListener('submit',event=>{if(event.target.id!=='newsletter-form')return;event.preventDefault();const email=document.getElementById('newsletter-email');const msg=document.getElementById('newsletter-message');if(!email.checkValidity()){email.reportValidity();return}msg.textContent='Thanks — you’re on the list for this demo.';email.value='';showToast('Thanks for being here')});
main.addEventListener('change',event=>{if(['filter-category','filter-size','filter-color','sort-order'].includes(event.target.id)){const p=currentParams();updateCollectionGrid(p.get('collection'),p.get('q')||'')}});
window.addEventListener('popstate',renderRoute);
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeCart();closeMobile()}});
renderCart();
renderRoute();
